-- KMI Paket B / 0132 POSTCHECK (READ-ONLY). Every ok must be true.
select 'migration recorded' chk, exists (select 1 from supabase_migrations.schema_migrations where name = '0132_tool_list_control') ok
union all select 'new functions exist', (select count(*) from pg_proc where pronamespace = 'kmi_next'::regnamespace and proname in ('toolist_file_kind','toolist_checks','toolist_checks_core','toolist_attest','toolist_recheck_done','toolist_overview','tl_chk','tl_norm','tg_toolist_pin','tg_toolist_recheck_guard','toolist_open_rechecks')) >= 11
union all select '3 evidence tables exist, RLS on, closed to anon/authenticated', (select count(*) from pg_class c where c.relnamespace = 'kmi_next'::regnamespace and c.relname in ('toolist_attestations','toolist_rechecks','work_order_tool_list_pins') and c.relrowsecurity) = 3 and not exists (select 1 from (values ('toolist_attestations'),('toolist_rechecks'),('work_order_tool_list_pins')) t(n) where has_table_privilege('authenticated', 'kmi_next.' || t.n, 'SELECT,INSERT,UPDATE,DELETE') or has_table_privilege('anon', 'kmi_next.' || t.n, 'SELECT,INSERT,UPDATE,DELETE'))
union all select 'public RPCs: authenticated yes, anon no', has_function_privilege('authenticated', 'kmi_next.toolist_checks(uuid)', 'EXECUTE') and has_function_privilege('authenticated', 'kmi_next.toolist_attest(uuid,jsonb,text)', 'EXECUTE') and not has_function_privilege('anon', 'kmi_next.toolist_checks(uuid)', 'EXECUTE') and not has_function_privilege('anon', 'kmi_next.toolist_attest(uuid,jsonb,text)', 'EXECUTE')
union all select 'internal helpers closed to API roles', not has_function_privilege('authenticated', 'kmi_next.toolist_file_kind(text,text,bytea)', 'EXECUTE') and not has_function_privilege('anon', 'kmi_next.toolist_file_kind(text,text,bytea)', 'EXECUTE')
union all select 'upload_document now accepts spreadsheets via toolist_file_kind', position('toolist_file_kind' in pg_get_functiondef('kmi_next.upload_document(text,text,uuid,text,text,text,text,date,text,uuid)'::regprocedure)) > 0
union all select 'publish gate present (document_publish checks attestation)', position('TOOLIST_ATTESTATION_REQUIRED' in pg_get_functiondef('kmi_next.document_publish(uuid,text)'::regprocedure)) > 0 and position('TOOLIST_CHECK_FAILED' in pg_get_functiondef('kmi_next.document_publish(uuid,text)'::regprocedure)) > 0
union all select 'start gate present (dc_start_refusal)', position('TOOL_LIST_REQUIRED' in pg_get_functiondef('kmi_next.dc_start_refusal(uuid,integer)'::regprocedure)) > 0
union all select 'pin trigger installed on work_order_operations', exists (select 1 from pg_trigger where tgname = 'work_order_operations_toolist_pin' and not tgisinternal)
union all select 'evidence tables empty right after apply (no data invented)', (select count(*) from kmi_next.toolist_attestations) + (select count(*) from kmi_next.toolist_rechecks) + (select count(*) from kmi_next.work_order_tool_list_pins) = 0
union all select '0128 pilot postcheck 10/10 unchanged', (select count(*) filter (where ok) = 10 from kmi_next.pilot_isolation_postcheck())
union all select '0129 functions untouched (13)', (select count(*) from pg_proc where pronamespace = 'kmi_next'::regnamespace and proname in ('cnc_activity','cnc_activity_summary','cnc_events','cnc_shift_summaries','cnc_connected_machines','cnc_segments_core','cnc_events_core','cnc_summary_core','cnc_wo_matched_seconds','cnc_device_of','cnc_view_guard','cnc_check_window','cnc_gap_seconds')) = 13
union all select 'pilot registry: toolist helpers classified KEEP (no UNCLASSIFIED consumers)', (select count(*) from kmi_next.pilot_consumer_registry where fn_identity in ('kmi_next.tg_toolist_pin()','kmi_next.toolist_checks_core(uuid)')) = 2 and not exists (select 1 from kmi_next.pilot_isolation_postcheck() where not ok);
